/* ========== LEVEL 4 · THEORY (university years 1–2) ========== */
/* semi-empirical mass formula: binding energy per nucleon, with the first n terms switched on */
function semfBA(A,n){var Z=A/(1.98+0.0155*Math.pow(A,2/3)),B=15.8*A;if(n>1)B-=18.3*Math.pow(A,2/3);if(n>2)B-=0.714*Z*(Z-1)/Math.pow(A,1/3);if(n>3)B-=23.2*Math.pow(A-2*Z,2)/A;return B/A}
/* PWR neutron spectrum per unit lethargy (qualitative): thermal Maxwellian + 1/E slowing down + fission spectrum */
function nSpec(E,T){var kT=8.617e-5*(T+273),x=E/kT,th=x*x*Math.exp(-x)/(4*Math.exp(-2)),ep=0.35*(1-Math.exp(-Math.pow(E/(8*kT),2)))*Math.exp(-E/3e6),g=Math.pow(E/1e6,1.5)*Math.exp(-E/1e6)/0.41*0.8;return th+ep+g}
function fYield(A){function h(d){return Math.exp(-Math.pow(Math.abs(d)/8,2.6))}return 6.4*h(A-95)+6.6*h(A-138)+0.01*Math.exp(-Math.pow((A-117)/30,2))}
/* pool boiling curve for water at 1 bar (heat flux in W/m², wall superheat in °C) */
function boilQ(dT){var chf=23,lf=120;if(dT<=chf)return Math.max(1500*Math.pow(dT,1.25),80*Math.pow(dT,3));if(dT<=lf){var f=Math.log(dT/chf)/Math.log(lf/chf);return Math.exp(Math.log(80*Math.pow(chf,3))*(1-f)+Math.log(2e4)*f)}return 2e4*Math.pow(dT/lf,1.3)}
function boilNuc(q){var lo=0.1,hi=23;for(var k=0;k<60;k++){var m=(lo+hi)/2;if(boilQ(m)<q)lo=m;else hi=m}return (lo+hi)/2}
function boilFilm(q){return 120*Math.pow(q/2e4,1/1.3)}
/* fracture toughness of ferritic vessel steel against temperature, shifted by irradiation */
function kic(T,s){return 40+160/(1+Math.exp(-(T-s)/20))}

U({id:'t4-1',track:'theory',level:4,title:'Deeper nuclear physics',icon:'B/A',color:'#7F77DD',desc:'The liquid-drop model of the nucleus, why only some nuclei fission with slow neutrons, fission products and the six delayed-neutron groups.',lessons:[
LH('t4-1-1','The liquid-drop model',10,'Treat the nucleus like a drop of liquid, and four simple terms predict the binding energy of almost every nucleus.',[
RM(`<ul><li><b>Binding energy</b>: the energy needed to pull a nucleus apart; binding energy per nucleon peaks near iron (Level 2 Theory).</li><li>Fission of heavy nuclei and fusion of light ones both release energy because they move towards the peak.</li><li>The strong force is short-range; the electric repulsion between protons is long-range.</li></ul>`),
T(`<h3>A nucleus as a drop</h3><p>Nucleons only feel their nearest neighbours through the strong force, a bit like molecules in a drop of water. That idea gives the <b>semi-empirical mass formula</b> (SEMF), which adds up four effects:</p><div class="eq">B = a<sub>V</sub>A − a<sub>S</sub>A<sup>2/3</sup> − a<sub>C</sub>Z(Z−1)/A<sup>1/3</sup> − a<sub>A</sub>(A−2Z)²/A</div>${KY([['B','total binding energy','MeV'],['A','mass number (protons + neutrons)',''],['Z','proton number',''],['a<sub>V</sub>, a<sub>S</sub>, a<sub>C</sub>, a<sub>A</sub>','constants fitted to real nuclei: about 15.8, 18.3, 0.71 and 23.2','MeV']],'A small fifth "pairing" term adds a bit for even numbers of protons and neutrons; we\'ll meet it next lesson.')}`),
W('flipCards',{cards:[['Volume term  +a<sub>V</sub>A','Every nucleon bonds to its neighbours, so binding grows with the number of nucleons.'],['Surface term  −a<sub>S</sub>A<sup>2/3</sup>','Nucleons on the surface have fewer neighbours, so they are less tightly bound. Surface area ∝ A<sup>2/3</sup>.'],['Coulomb term  −a<sub>C</sub>Z(Z−1)/A<sup>1/3</sup>','Every pair of protons repels. This grows fast with Z and is why heavy nuclei are less tightly bound.'],['Asymmetry term  −a<sub>A</sub>(A−2Z)²/A','Nuclei prefer equal numbers of protons and neutrons; too many of either costs energy.']]},`Flip each card to see what each term means.`),
W('fnPlot',{x:[10,250],y:[0,12],xl:'mass number A',yl:'binding energy per nucleon (MeV)',sl:[['n','Terms switched on',1,4,1,1,function(v){return ['1: volume only','2: + surface','3: + Coulomb','4: + asymmetry (full model)'][v-1]}]],lines:[[8.8,'--muted']],curves:function(p){return [[function(A){return semfBA(A,p.n)},'--accent',3]]},read:function(p){if(p.n<4)return 'Add the next term and watch the curve change shape.';return 'Full model: peak about <b>'+semfBA(56,4).toFixed(2)+' MeV</b> near A = 56 (iron). U-235 about '+semfBA(235,4).toFixed(2)+' MeV. Real values: 8.79 and 7.59.'},goal:function(p){return p.n===4},goalMsg:'Switch on all four terms.'},`Build the binding energy curve one term at a time.`,`Four simple ideas reproduce the real curve to within about 1%.`),
Q(`Why does binding energy per nucleon fall for very heavy nuclei?`,[`Proton–proton electric repulsion grows faster than the strong-force binding`,'The surface term grows, so nucleons at the edge are less tightly held','There are too few neutrons, so the strong force can\'t hold them together','The strong force gets stronger, which pushes the nucleons further apart'],0,`The Coulomb term grows roughly as Z²/A<sup>1/3</sup>, faster than the volume term.`),
W('stepCalc',{steps:['U-235 splits into two fragments of about A = 117 each.','Binding energy per nucleon: U-235 about 7.6 MeV; A = 117 about 8.5 MeV.','Gain per nucleon: 8.5 − 7.6 = 0.9 MeV','Total: 0.9 × 235 ≈ <b>210 MeV</b> per fission','Close to the measured ~200 MeV. The liquid-drop model explains where fission energy comes from.']},`Estimate the energy from one fission using the curve.`),
QE(`Binding energy per nucleon peaks near…`,[`iron-56`,`uranium-235`,`helium-4`,`hydrogen`],0,`Level 2 Theory.`),
T(`<h3>Key points</h3><ul><li>The <b>SEMF</b>: volume − surface − Coulomb − asymmetry (+ pairing).</li><li>Coulomb repulsion makes heavy nuclei less tightly bound: the reason fission releases energy.</li><li>Moving from B/A ≈ 7.6 to 8.5 gives about <b>200 MeV per fission</b>.</li></ul>`)]),
LH('t4-1-2','The fission barrier: fissile and fertile',10,'Why U-235 fissions with a slow neutron but U-238 needs a fast one.',[
RM(`<ul><li>Fissile: fissions with slow (thermal) neutrons, e.g. U-235. Fertile: becomes fissile after capturing a neutron, e.g. U-238 → Pu-239 (Level 2 Theory).</li><li>The SEMF has surface and Coulomb terms.</li></ul>`),
T(`<h3>A hill to climb</h3><p>To split, a nucleus must stretch into a peanut shape. Stretching increases the surface (costs energy) but separates the protons a little (gives back some). At first the surface cost wins, so there's an energy hill: the <b>fission barrier</b>, about <b>6 MeV</b> for uranium.</p><p>Something must supply about 6 MeV of excitation to get over it.</p>`),
T(`<h3>Where the energy comes from</h3><p>When a nucleus captures a neutron, it gains the neutron's <b>binding energy</b> as excitation, plus the neutron's kinetic energy.</p><table><tr><th>Capture</th><th>Energy gained</th><th>Barrier</th><th>Result</th></tr><tr><td>U-235 + n → U-236</td><td>6.5 MeV</td><td>about 6.2 MeV</td><td>Fissions even with a slow neutron</td></tr><tr><td>U-238 + n → U-239</td><td>4.8 MeV</td><td>about 6.6 MeV</td><td>Needs a neutron with more than about 1 MeV</td></tr></table>`),
W('stepCalc',{steps:['Why does U-235 get more energy from capture than U-238?','U-235 has an <b>odd</b> number of neutrons (143). Adding one makes 144: an even number.','Neutrons (like protons) like to pair up. Completing a pair releases extra <b>pairing energy</b>, about 1–2 MeV.','U-238 already has an even number (146). The 147th neutron is unpaired: no bonus.','So nuclei with an odd number of neutrons (U-233, U-235, Pu-239, Pu-241) are <b>fissile</b>.']},`Find out why pairing decides which nuclei are fissile.`),
W('sortIt',{bins:['Fissile (fissions with thermal neutrons)','Fertile (becomes fissile after capture)'],items:[['Uranium-235',0],['Uranium-238',1],['Plutonium-239',0],['Thorium-232',1],['Uranium-233',0],['Plutonium-241',0]]},`Sort each nucleus.`),
Q(`U-238 can still fission in a reactor. When?`,[`When hit by a fast neutron above about 1 MeV`,'Never: U-238 can only absorb neutrons','Only when hit by a slow, thermal neutron','Only after shutdown, as the fuel cools'],0,`Fast fission of U-238 provides several percent of PWR power.`),
QE(`Thorium-232 captures a neutron and, after two beta decays, becomes…`,[`uranium-233`,`uranium-235`,`plutonium-239`,`thorium-233 permanently`],0,`Th-232 → Th-233 → Pa-233 → U-233.`),
T(`<h3>Key points</h3><ul><li>The <b>fission barrier</b> is about 6 MeV for heavy nuclei.</li><li>Capturing a neutron gives its binding energy; odd-neutron nuclei gain extra <b>pairing energy</b>.</li><li>Fissile: U-233, U-235, Pu-239, Pu-241. Fertile: U-238, Th-232.</li></ul>`)]),
LH('t4-1-3','Fission products and delayed neutrons',10,'Fission rarely splits evenly, and a tiny fraction of neutrons arrive late, which is what makes reactors controllable.',[
RM(`<ul><li><b>Delayed neutrons</b> (about 0.65% for U-235) come from decaying fission products and make control possible (Level 2 Theory, Level 3 Maths).</li><li>β is the delayed neutron fraction.</li></ul>`),
T(`<h3>Uneven splits</h3><p>Fission of U-235 usually gives one lighter and one heavier fragment. The <b>fission yield</b> curve has two humps, near A ≈ 95 and A ≈ 138, each with about 6% of fissions per mass number. An even split (A ≈ 117) is about 600 times less likely.</p>`),
W('fnPlot',{x:[70,170],y:[0.001,10],ylog:true,xl:'mass number of fragment',yl:'yield (% per fission)',sl:[['a','Look at mass number',70,165,1,135,function(v){return 'A = '+v}]],curves:function(p){return [[fYield,'--accent',3]]},marks:function(p,P,col){var c=P.c,y=fYield(p.a);c.fillStyle=col('--coral');c.beginPath();c.arc(P.X(p.a),P.Y(y),6,0,7);c.fill()},read:function(p){var y=fYield(p.a),note=Math.abs(p.a-135)<1?' Xenon-135 sits here (about 6.5% with its parent iodine).':Math.abs(p.a-90)<1?' Strontium-90 sits here.':Math.abs(p.a-137)<1?' Caesium-137 sits here.':'';return 'A = '+p.a+': yield about <b>'+(y<0.1?y.toFixed(3):y.toFixed(1))+'%</b>.'+note}},`Slide along the double-humped fission yield curve (log scale).`),
T(`<h3>Six groups of delayed neutrons</h3><p>Some fission products (precursors such as bromine-87) beta-decay into a nucleus with so much energy that it immediately emits a neutron. Physicists group the precursors into <b>six groups</b> by half-life:</p><table><tr><th>Group</th><th>Half-life</th></tr><tr><td>1</td><td>about 55 s</td></tr><tr><td>2</td><td>about 22 s</td></tr><tr><td>3</td><td>about 6 s</td></tr><tr><td>4</td><td>about 2 s</td></tr><tr><td>5</td><td>about 0.5 s</td></tr><tr><td>6</td><td>about 0.2 s</td></tr></table><p>Weighted together, a delayed neutron arrives about <b>13 s</b> after its fission on average, compared with about 20 microseconds for a prompt neutron.</p>`),
W('stepCalc',{steps:['Prompt neutron lifetime in a PWR: ℓ ≈ 2 × 10<sup>−5</sup> s','Delayed fraction β = 0.0065, average delay τ ≈ 13 s','Average generation time ≈ (1 − β)ℓ + β(ℓ + τ)','≈ 0.00002 + 0.0065 × 13 ≈ <b>0.085 s</b>','The tiny delayed fraction makes the average generation about <b>4,000 times</b> longer, slow enough to control.']},`See how 0.65% of neutrons slows the whole reactor down.`),
T(`<h3>β changes through life</h3><table><tr><th>Fissioning nucleus</th><th>β</th></tr><tr><td>U-235</td><td>0.0065</td></tr><tr><td>Pu-239</td><td>0.0021</td></tr><tr><td>U-238 (fast fission)</td><td>0.0148</td></tr></table><p>As plutonium builds up through a fuel cycle, the core's effective β falls, so the reactor becomes <b>more responsive</b> to reactivity changes at end of cycle.</p>`),
QE(`Prompt critical means reactivity equals…`,[`β`,`zero`,`1`,`k∞`],0,`Level 3 Maths.`),
T(`<h3>Key points</h3><ul><li>Fission yield is <b>double-humped</b>: peaks near A ≈ 95 and 138.</li><li>Delayed neutrons come in <b>six groups</b>, half-lives 0.2–55 s, average delay ~13 s.</li><li>β: U-235 0.0065, Pu-239 0.0021. β<sub>eff</sub> falls as plutonium builds up.</li></ul>`)])
]});
F('t4-1-1',[T(`<h3>Quick recap</h3><p>SEMF: volume − surface − Coulomb − asymmetry.</p>`),Q(`Which term favours equal numbers of protons and neutrons?`,[`Asymmetry`,`Volume`,`Surface`,`Coulomb`],0,`(A − 2Z)².`),Q(`The surface term scales as…`,[`A<sup>2/3</sup>`,`A`,`A²`,`1/A`],0,`Area of a sphere ∝ r² ∝ A<sup>2/3</sup>.`),N(`B/A rises from 7.6 to 8.5 MeV across 235 nucleons. Energy released (MeV)?`,211.5,0.05,'MeV',`0.9 × 235.`)]);
F('t4-1-2',[T(`<h3>Quick recap</h3><p>Barrier ~6 MeV; pairing energy decides fissile vs fertile.</p>`),Q(`Pu-239 has 145 neutrons. Adding one makes an even number, so it is…`,[`fissile`,`fertile`,`stable`,`non-fissionable`],0,`Pairing bonus.`),Q(`U-238 captures give about…`,[`4.8 MeV, below the barrier`,`6.5 MeV, above it`,`200 MeV`,`0 MeV`],0,`No pairing bonus.`),Q(`The fission barrier exists because…`,[`stretching the nucleus increases surface energy first`,`neutrons repel`,`electrons block it`,`of gravity`],0,`Surface term.`)]);
F('t4-1-3',[T(`<h3>Quick recap</h3><p>Two-humped yield; six delayed groups; β falls with Pu.</p>`),Q(`An even split of U-235 is…`,[`very unlikely (about 0.01%)`,`the most likely`,`impossible`,`50% likely`],0,`Valley of the curve.`),Q(`Longest delayed group half-life is about…`,[`55 s`,`5 s`,`9 h`,`20 μs`],0,`Bromine-87.`),Q(`At end of cycle the core is more responsive because…`,[`plutonium has a smaller β`,`boron is high`,`xenon is gone`,`the fuel is cold`],0,`β<sub>eff</sub> falls.`)]);
TT('t4-1',[x('t4-1-1',Q(`The Coulomb term in the SEMF represents…`,[`proton–proton repulsion`,`neutron pairing`,`surface tension`,`nucleon count`],0,`Electric.`)),x('t4-1-1',Q(`Fission releases energy because the fragments…`,[`have higher binding energy per nucleon`,`have more mass`,`are lighter than electrons`,`are radioactive`],0,`Moving up the curve.`)),x('t4-1-2',Q(`Which is fertile?`,[`Thorium-232`,`Uranium-235`,`Plutonium-239`,`Uranium-233`],0,`Becomes U-233.`)),x('t4-1-2',Q(`Odd-neutron nuclei are fissile because capture gives…`,[`extra pairing energy`,`more protons`,`less mass`,`a higher barrier`],0,`Pairing.`)),x('t4-1-3',Q(`The fission yield curve peaks near A =…`,[`95 and 138`,`117`,`56`,`235`],0,`Two humps.`)),x('t4-1-3',Q(`β for Pu-239 is about…`,[`0.0021`,`0.0065`,`0.0148`,`0.065`],0,`About a third of U-235's.`))]);

U({id:'t4-2',track:'theory',level:4,title:'Neutron spectra and breeding',icon:'η',color:'#378ADD',desc:'The neutron energy spectrum, slowing down in steps of lethargy, thermal versus fast reactors, conversion and breeding.',lessons:[
LH('t4-2-1','The neutron energy spectrum',10,'Neutrons are born fast, slow down in a series of collisions, and end up in thermal balance with the water.',[
RM(`<ul><li>Fission neutrons are born with about 2 MeV; thermal neutrons have about 0.025 eV (Level 2 Theory).</li><li>Moderation: slowing neutrons by collisions; hydrogen is best because it has the same mass as a neutron.</li><li>ln undoes e (Level 2 Maths).</li></ul>`),
T(`<h3>Three regions</h3><p>If you counted the neutrons in a PWR core at each energy, you'd see three regions:</p><ol class="steps"><li><b>Fast (fission spectrum)</b>: 0.1–10 MeV, average about 2 MeV. Where neutrons are born.</li><li><b>Slowing down (epithermal)</b>: 1 eV to 0.1 MeV. Neutrons losing energy collision by collision; resonances in U-238 live here.</li><li><b>Thermal</b>: below about 1 eV. Neutrons in balance with the hot water. Their typical energy is kT ≈ 0.05 eV at 300 °C (k is Boltzmann's constant, T the temperature in kelvin).</li></ol>`),
T(`<h3>Lethargy: a better scale</h3><p>Each collision with hydrogen removes, on average, the same <b>fraction</b> of a neutron's energy, not the same amount. So it's natural to measure progress on a log scale called <b>lethargy</b>:</p><div class="eq">u = ln(E₀ / E)</div><p>The average gain in lethargy per collision is called <b>ξ</b> (xi): 1.0 for hydrogen, 0.16 for carbon, 0.008 for uranium-238.</p>`),
W('fnPlot',{x:[0.001,2e7],xlog:true,y:[0,1.3],xl:'neutron energy (eV, log scale)',yl:'neutrons per unit lethargy (relative)',sl:[['t','Water temperature',20,320,10,300,function(v){return v+' °C'}]],curves:function(p){return [[function(E){return nSpec(E,p.t)},'--accent',3]]},read:function(p){var kT=8.617e-5*(p.t+273);return 'On this plot the thermal peak sits at 2kT = <b>'+(2*kT).toFixed(3)+' eV</b>. The flat middle is the slowing-down region; the bump at the right is the fission spectrum (around 1–2 MeV).'}},`The neutron spectrum in a PWR core. Change the water temperature and watch the thermal peak move.`),
W('stepCalc',{steps:['From 2 MeV to 0.025 eV: total lethargy u = ln(2,000,000 ÷ 0.025)','= ln(8 × 10<sup>7</sup>) ≈ <b>18.2</b>','Collisions needed = u ÷ ξ','Hydrogen (ξ = 1.0): about <b>18 collisions</b>','Carbon (ξ = 0.16): about <b>115 collisions</b>. That\'s why graphite reactors need so much more moderator.']},`How many collisions to thermalise a neutron?`),
N(`Deuterium has ξ = 0.725. About how many collisions to go from 2 MeV to 0.025 eV? (u = 18.2)`,25.1,0.05,'collisions',`18.2 ÷ 0.725 ≈ 25.`),
QE(`Why is hydrogen the best moderator per collision?`,[`Its nucleus has about the same mass as a neutron`,`It absorbs neutrons strongly, so they stop quickly`,`Its nucleus is heavy, so neutrons bounce off it hard`,`It is radioactive, so it gives neutrons extra energy`],0,`Like equal snooker balls (Level 2 Theory).`),
T(`<h3>Key points</h3><ul><li>Spectrum: <b>fast</b> (birth), <b>slowing down</b> (resonances), <b>thermal</b> (balance with the water).</li><li><b>Lethargy u = ln(E₀/E)</b>; ξ is the average gain per collision.</li><li>About 18 collisions in hydrogen, 115 in carbon.</li></ul>`)]),
LH('t4-2-2','Thermal and fast reactors',10,'Remove the moderator and the neutrons stay fast. What changes, and why some designs do it on purpose.',[
RM(`<ul><li>Neutron spectrum: fast, slowing down, thermal.</li><li>Fission cross-sections are much bigger for slow neutrons (Level 2 Theory).</li></ul>`),
T(`<h3>η: neutrons out per neutron absorbed</h3><p>When a fissile nucleus <b>absorbs</b> a neutron, it doesn't always fission (sometimes it just captures). The useful number is:</p><div class="eq">η = ν σ<sub>f</sub> ÷ σ<sub>a</sub></div>${KY([['η','neutrons produced per neutron absorbed in the fuel',''],['ν','neutrons per fission (about 2.4–2.9)',''],['σ<sub>f</sub>, σ<sub>a</sub>','fission and total absorption cross-sections','barns']])}<table><tr><th>Nucleus</th><th>η thermal</th><th>η fast</th></tr><tr><td>U-235</td><td>2.07</td><td>about 2.3</td></tr><tr><td>Pu-239</td><td>2.11</td><td>about 2.9</td></tr><tr><td>U-233</td><td>2.29</td><td>about 2.4</td></tr></table>`),
T(`<h3>Why η matters for breeding</h3><p>To <b>breed</b> (make more fuel than you burn), each absorption must supply: 1 neutron to keep the chain reaction going, plus at least 1 to convert a fertile nucleus, plus some lost to leakage and parasitic capture. So you need <b>η well above 2</b>.</p><p>Pu-239 in a <b>fast</b> spectrum (η ≈ 2.9) can do it easily. That's why breeder reactors are fast reactors, cooled by liquid sodium or lead rather than water (water would moderate the neutrons).</p>`),
W('matchPairs',{pairs:[['PWR (like Hinkley Point C)','Thermal spectrum, water moderated and cooled'],['Sodium-cooled fast reactor','No moderator, breeds plutonium'],['AGR (UK)','Thermal, graphite moderated, CO₂ cooled'],['Molten salt reactor','Fuel dissolved in liquid salt; can breed U-233 from thorium']]},`Match each reactor to its description.`),
Q(`Why is water not used to cool a fast breeder?`,[`It would slow the neutrons down`,'It is too expensive to keep pure at high temperature','It boils at 100 °C, so it can\'t carry enough heat','It absorbs too few neutrons to control the reactor'],0,`Hydrogen is a great moderator: exactly what a fast reactor must avoid.`),
QE(`What does k∞ leave out?`,[`Leakage`,`Fission`,`Absorption`,`Moderation`],0,`Infinite medium (Level 2 Theory).`),
T(`<h3>Key points</h3><ul><li><b>η = νσ<sub>f</sub>/σ<sub>a</sub></b>: neutrons per absorption.</li><li>Breeding needs η comfortably above 2: <b>Pu-239 in a fast spectrum</b>.</li><li>Fast reactors use sodium, lead or gas coolants, not water.</li></ul>`)]),
LH('t4-2-3','Conversion and breeding ratio',10,'Every PWR makes plutonium as it runs. How much, and how much of the power it ends up supplying.',[
RM(`<ul><li>U-238 + n → U-239 → Np-239 → Pu-239 (two beta decays) (Level 2 Theory).</li><li>Breeding needs η above 2.</li></ul>`),
T(`<h3>The conversion ratio</h3><div class="eq">CR = fissile nuclei made ÷ fissile nuclei destroyed</div><table><tr><th>CR</th><th>Name</th><th>Example</th></tr><tr><td>below 1</td><td>Converter</td><td>PWR: about 0.5–0.6</td></tr><tr><td>above 1</td><td>Breeder (CR is then called the breeding ratio)</td><td>Fast breeder: about 1.2–1.3</td></tr></table>`),
W('stepCalc',{steps:['A PWR destroys 100 U-235 nuclei.','With CR = 0.6, it makes 60 new Pu-239 nuclei.','Some of those fission too: 60 × 0.6 = 36 more made…','Total fissile burned: 100 + 60 + 36 + … = 100 ÷ (1 − 0.6) = <b>250</b>','So the fuel supports about 2.5 times as many fissions as its original U-235 alone. In practice by end of life, about <b>a third</b> of a PWR\'s power comes from plutonium.']},`See how conversion stretches the fuel.`),
N(`CR = 0.5. Total fissile nuclei burned per 100 original U-235 (geometric series)?`,200,0.01,'',`100 ÷ (1 − 0.5) = 200.`),
Q(`What is "doubling time" for a breeder?`,[`The time to produce enough surplus fuel to start another reactor`,'The time for the reactor\'s power to double during a startup','The reactor period: how long power takes to rise by a factor of e','The time for half the plutonium in the core to be used up'],0,`Depends on breeding ratio and fuel inventory; decades for most designs.`),
QE(`In a PWR, plutonium building up makes β<sub>eff</sub>…`,[`fall`,`rise`,`stay the same`,`zero`],0,`Last unit.`),
T(`<h3>Key points</h3><ul><li><b>CR = fissile made ÷ fissile destroyed</b>.</li><li>PWR: CR ≈ 0.6, a converter; about a third of its energy ends up coming from plutonium.</li><li>Breeder: CR > 1, needs a fast spectrum.</li></ul>`)])
]});
F('t4-2-1',[T(`<h3>Quick recap</h3><p>u = ln(E₀/E); collisions = u/ξ.</p>`),N(`Lethargy from 1 MeV to 1 eV? (ln 10⁶ = 13.8)`,13.8,0.01,'',`ln(10⁶).`),Q(`U-238 resonances are in the…`,[`slowing-down region`,`thermal region`,`fission spectrum`,`not in a reactor`],0,`Epithermal.`),Q(`Graphite needs more collisions than water because…`,[`carbon is heavier, so ξ is smaller`,`it absorbs more`,`it is solid`,`it is hotter`],0,`ξ = 0.16.`)]);
F('t4-2-2',[T(`<h3>Quick recap</h3><p>η = νσ<sub>f</sub>/σ<sub>a</sub>; breeding needs η > 2.</p>`),Q(`η for Pu-239 is highest in a…`,[`fast spectrum`,`thermal spectrum`,`resonance region`,`cold reactor`],0,`About 2.9.`),Q(`One neutron per absorption must go to…`,[`keeping the chain reaction going`,`leakage`,`the turbine`,`xenon`],0,`Then one more to breed.`),Q(`Which isotope gives η > 2 in a thermal spectrum, allowing thermal breeding?`,[`U-233`,`U-238`,`Th-232`,`B-10`],0,`η ≈ 2.29: the thorium cycle.`)]);
F('t4-2-3',[T(`<h3>Quick recap</h3><p>CR = made/destroyed; total burned = 1/(1 − CR).</p>`),N(`CR = 0.8: total burned per 100 original?`,500,0.01,'',`100/0.2.`),Q(`CR > 1 means…`,[`a breeder`,`a converter`,`subcritical`,`no plutonium`],0,`Breeding ratio.`),Q(`About what share of a PWR's energy comes from plutonium by end of life?`,[`about a third`,`none`,`all of it`,`about 1%`],0,`Bred in place.`)]);
TT('t4-2',[x('t4-2-1',Q(`Lethargy measures…`,[`log of energy lost`,`speed`,`absorption`,`flux`],0,`u = ln(E₀/E).`)),x('t4-2-1',N(`u = 18.2, ξ = 1. Collisions?`,18.2,0.02,'',`u/ξ.`)),x('t4-2-2',Q(`η is…`,[`neutrons produced per neutron absorbed in fuel`,`neutrons per fission`,`the reproduction of the core`,`efficiency`],0,`νσ<sub>f</sub>/σ<sub>a</sub>.`)),x('t4-2-2',Q(`Fast breeders use…`,[`sodium or lead coolant`,`light water`,`heavy water moderator`,`graphite`],0,`No moderation.`)),x('t4-2-3',Q(`A PWR's conversion ratio is about…`,[`0.6`,`1.2`,`0`,`2.4`],0,`Converter.`)),x('t4-2-3',N(`CR = 0.6. Burned per 100 original?`,250,0.01,'',`100/0.4.`))]);

U({id:'t4-3',track:'theory',level:4,title:'Two-phase flow and boiling',icon:'CHF',color:'#1D9E75',desc:'Quality and void fraction, flow patterns, the boiling curve and the critical heat flux that limits every water reactor.',lessons:[
LH('t4-3-1','Quality and void fraction',10,'A little steam by mass takes up a lot of space. Why that matters for moderation and for heat transfer.',[
RM(`<ul><li><b>Steam quality x</b>: the fraction of the mass that is vapour (Level 2 Theory).</li><li>Saturation temperature rises with pressure: 100 °C at 1 bar, 345 °C at 155 bar.</li><li>Steam voids reduce moderation (Level 3 Theory).</li></ul>`),
T(`<h3>Two different fractions</h3><p><b>Quality x</b> is a mass fraction. <b>Void fraction α</b> is a <b>volume</b> fraction: how much of the channel is filled with vapour.</p><p>Because steam is much less dense than water, a small mass of steam fills a large volume. If both phases move at the same speed:</p><div class="eq">α = 1 ÷ [1 + ((1 − x)/x) × (ρ<sub>g</sub>/ρ<sub>l</sub>)]</div>${KY([['α','void fraction','0 to 1'],['x','quality (mass fraction of vapour)','0 to 1'],['ρ<sub>g</sub>, ρ<sub>l</sub>','density of vapour and of liquid','kg/m³']])}`),
W('fnPlot',{x:[0,1],y:[0,1],xl:'quality x',yl:'void fraction α',sl:[['p','Pressure',0,2,1,1,function(v){return ['1 bar','70 bar (BWR)','155 bar (PWR)'][v]}]],curves:function(p){var r=[0.000624,0.0493,0.1716][p.p];return [[function(x){return x<=0?0:1/(1+(1-x)/x*r)},'--accent',3],[function(x){return x},'--muted',1.5,[6,4]]]},read:function(p){var r=[0.000624,0.0493,0.1716][p.p],a=1/(1+9*r);return ['1 bar','70 bar','155 bar'][p.p]+': at x = 0.1, α = <b>'+(a*100).toFixed(0)+'%</b>. Dashed line: α = x.'}},`Change the pressure and see how much of the channel 10% quality fills.`),
N(`At 70 bar, ρ<sub>g</sub>/ρ<sub>l</sub> = 0.049. What is α for x = 0.05? (as a decimal)`,0.517,0.02,'',`(0.95/0.05) × 0.049 = 0.931; α = 1/1.931 = 0.52.`),
Q(`Why does high pressure reduce the void fraction for the same quality?`,[`Steam is denser at high pressure, so it takes less room`,'Water expands at high pressure, so it fills more space','High pressure condenses all the steam back into water','It doesn\'t: void fraction only depends on the quality'],0,`ρ<sub>g</sub>/ρ<sub>l</sub> rises with pressure.`),
QE(`Water at 155 bar boils at about…`,[`345 °C`,`100 °C`,`290 °C`,`500 °C`],0,`Level 2 Theory.`),
T(`<h3>Key points</h3><ul><li><b>Quality</b> is by mass; <b>void fraction</b> is by volume.</li><li>A few percent quality can be over half the volume at low pressure.</li><li>Higher pressure → denser steam → smaller voids.</li></ul>`)]),
LH('t4-3-2','The boiling curve',10,'Heat a surface under water and the heat transfer changes dramatically as it gets hotter, then suddenly gets much worse.',[
RM(`<ul><li>Convection: q″ = h ΔT (Level 4 Maths).</li><li>Nucleate boiling: bubbles form at the hot surface and carry heat away very effectively (Level 2 Theory).</li></ul>`),
T(`<h3>Nukiyama's experiment</h3><p>In 1934, Shiro Nukiyama heated a wire in water and measured the heat flux against the wire's <b>superheat</b> (how far it was above the boiling point). He found four regions:</p><ol class="steps"><li><b>Natural convection</b>: no bubbles yet.</li><li><b>Nucleate boiling</b>: bubbles form and break away; heat flux rises very steeply.</li><li><b>Transition boiling</b>: patches of vapour start to cover the surface; heat flux <b>falls</b>.</li><li><b>Film boiling</b>: a continuous vapour blanket insulates the surface.</li></ol><p>The peak between nucleate and transition boiling is the <b>critical heat flux (CHF)</b>.</p>`),
W('fnPlot',{x:[1,3000],y:[1000,3e6],xlog:true,ylog:true,xl:'wall superheat (°C)',yl:'heat flux (W/m²)',sl:[['q','Heat flux the fuel makes (MW/m²)',0.1,1.2,0.05,0.5,function(v){return v.toFixed(2)+' MW/m²'}]],lines:[[boilQ(23),'--muted']],curves:function(){return [[boilQ,'--accent',3]]},marks:function(p,P,col){var q=p.q*1e6,chf=boilQ(23),dT=q<chf?boilNuc(q):boilFilm(q),c=P.c;c.fillStyle=col('--coral');c.beginPath();c.arc(P.X(Math.min(dT,3000)),P.Y(q),7,0,7);c.fill()},read:function(p){var q=p.q*1e6,chf=boilQ(23);if(q<chf)return 'Nucleate boiling: the wall is only <b>'+boilNuc(q).toFixed(0)+' °C</b> above the water. Very efficient.';var dT=boilFilm(q);return '<b>Above CHF!</b> The only steady state is film boiling: wall superheat jumps to about <b>'+(dT>3000?'3,000+':dT.toFixed(0))+' °C</b>.'},goal:function(p){return p.q*1e6>boilQ(23)},goalMsg:'Push the heat flux above the peak (CHF) and see what happens.'},`The fuel decides the heat flux. Push it past the peak.`,`Because fuel sets the heat flux, passing CHF makes the surface temperature jump hundreds of degrees: a "boiling crisis".`),
Q(`Why can't the surface just sit in transition boiling?`,[`The fuel sets the heat flux; transition boiling can't carry it, so the temperature runs away to film boiling`,'Transition boiling carries away too much heat, so the fuel cools far below the coolant temperature','The water flashes to ice on the hot surface, which blocks the flow past the fuel completely','It can, safely: the surface settles in transition boiling and the temperature stays steady'],0,`With heat flux controlled, the curve to the right of CHF is unreachable steadily.`),
QE(`The heat flux at a fuel rod surface is roughly…`,[`0.5–0.6 MW/m² on average`,`5–6 W/m² on average`,`500–600 MW/m² on average`,`50–60 kW/m² on average`],0,`570,000 W/m² at 17 kW/m (Level 4 Maths).`),
T(`<h3>Key points</h3><ul><li>Four regions: natural convection, <b>nucleate</b>, transition, <b>film</b> boiling.</li><li>The peak is the <b>critical heat flux (CHF)</b>.</li><li>For heat-flux-controlled surfaces like fuel, passing CHF causes a sudden large temperature rise.</li><li>Water at 1 bar: CHF ~1 MW/m². At PWR pressure and flow it's a few MW/m², but the shape is the same.</li></ul>`)]),
LH('t4-3-3','DNB and dryout',10,'Two ways to reach the boiling crisis, and the margin designers keep from each.',[
RM(`<ul><li>CHF: the peak of the boiling curve.</li><li>DNBR: predicted CHF ÷ actual heat flux, kept above a limit (Level 3 Theory).</li><li>Flow patterns change as quality rises.</li></ul>`),
T(`<h3>Flow patterns up a heated channel</h3><p>As water flows up a heated channel and more of it boils, the pattern changes.</p>`),
O(`Put the flow patterns in order, from the bottom of a boiling channel to the top.`,[`Single-phase liquid`,`Bubbly flow`,`Slug flow (big bullet-shaped bubbles)`,`Churn flow`,`Annular flow (liquid film on the wall, vapour core)`,`Mist flow (droplets in vapour)`],`Quality increases upwards, so the vapour takes over more of the channel.`),
T(`<h3>Two kinds of boiling crisis</h3><table><tr><th></th><th>Departure from nucleate boiling (DNB)</th><th>Dryout</th></tr><tr><td>Where</td><td>Low quality or subcooled flow: <b>PWRs</b></td><td>High quality, annular flow: <b>BWRs</b></td></tr><tr><td>What happens</td><td>Bubbles crowd together and form a vapour blanket on the wall</td><td>The thin liquid film on the wall evaporates away</td></tr><tr><td>Temperature rise</td><td>Sharp and fast</td><td>Usually slower and smaller</td></tr><tr><td>Margin</td><td><b>DNBR</b></td><td>Critical power ratio (CPR)</td></tr></table>`),
W('stepCalc',{steps:['The hot channel: predicted CHF from a correlation (tested in full-scale rod bundles) = 2.8 MW/m²','Actual local heat flux at the hottest point = 1.6 MW/m²','DNBR = 2.8 ÷ 1.6 = <b>1.75</b>','Design limit (depends on the correlation): about 1.2–1.3','Margin is fine. Protection systems trip the reactor if calculated DNBR approaches the limit.']},`Work out a DNB ratio.`),
N(`Predicted CHF 2.4 MW/m², actual heat flux 1.6 MW/m². DNBR?`,1.5,0.01,'',`2.4 ÷ 1.6 = 1.5.`),
QE(`Which mainly sets the trip on low DNBR in a PWR?`,[`Pressure, temperature, flow and power distribution`,`Boron concentration and nothing else`,`Turbine speed, steam flow and generator output`,`Grid frequency, condenser vacuum and feed flow`],0,`They all feed the DNBR calculation (Level 3 Theory).`),
T(`<h3>Key points</h3><ul><li>Flow patterns: bubbly → slug → churn → annular → mist.</li><li><b>DNB</b> (PWR, low quality) vs <b>dryout</b> (BWR, annular flow).</li><li>DNBR = predicted CHF ÷ actual heat flux; limit about 1.2–1.3.</li></ul>`)])
]});
F('t4-3-1',[T(`<h3>Quick recap</h3><p>α = 1/[1 + ((1−x)/x)(ρ<sub>g</sub>/ρ<sub>l</sub>)].</p>`),Q(`Void fraction is a fraction of…`,[`volume`,`mass`,`energy`,`time`],0,`Quality is mass.`),N(`ρ<sub>g</sub>/ρ<sub>l</sub> = 0.1, x = 0.5. α?`,0.909,0.01,'',`1/(1 + 1 × 0.1).`),Q(`At 1 bar, 10% quality gives a void fraction of about…`,[`99%`,`10%`,`50%`,`1%`],0,`Steam is 1,600 times less dense.`)]);
F('t4-3-2',[T(`<h3>Quick recap</h3><p>Natural convection → nucleate → CHF → transition → film.</p>`),Q(`The most effective heat transfer is in…`,[`nucleate boiling`,`film boiling`,`natural convection`,`transition boiling`],0,`Steep part of the curve.`),Q(`Who first measured the boiling curve?`,[`Nukiyama`,`Fermi`,`Rutherford`,`Bernoulli`],0,`1934.`),Q(`In film boiling the surface is covered by…`,[`a vapour blanket`,`bubbles that break away`,`ice`,`oxide`],0,`Insulating.`)]);
F('t4-3-3',[T(`<h3>Quick recap</h3><p>DNB in PWRs, dryout in BWRs; DNBR = CHF/q″.</p>`),N(`CHF 3.0, q″ 2.0 MW/m². DNBR?`,1.5,0.01,'',`3/2.`),Q(`Annular flow has…`,[`a liquid film on the wall and vapour in the middle`,`only bubbles`,`only liquid`,`only droplets`],0,`High quality.`),Q(`DNB is the main concern for…`,[`PWRs`,`BWRs`,`fast reactors`,`AGRs`],0,`Low quality flow.`)]);
TT('t4-3',[x('t4-3-1',Q(`Higher pressure gives a void fraction that is…`,[`smaller for the same quality`,`larger`,`the same`,`always zero`],0,`Denser steam.`)),x('t4-3-1',N(`ρ<sub>g</sub>/ρ<sub>l</sub> = 0.2, x = 0.2. α?`,0.556,0.01,'',`1/(1 + 4 × 0.2).`)),x('t4-3-2',Q(`CHF is the…`,[`peak of the boiling curve`,`start of boiling`,`film boiling minimum`,`saturation temperature`],0,`Critical heat flux.`)),x('t4-3-2',Q(`Passing CHF in fuel causes…`,[`a sudden large rise in cladding temperature`,`better cooling`,`no change`,`lower power`],0,`Boiling crisis.`)),x('t4-3-3',Q(`Dryout happens in…`,[`annular flow at high quality`,`subcooled flow`,`single-phase liquid`,`bubbly flow`],0,`Film evaporates.`)),x('t4-3-3',Q(`A DNBR of 1.0 means…`,[`the heat flux has reached the predicted CHF`,`plenty of margin`,`no boiling`,`shutdown`],0,`No margin left.`))]);

U({id:'t4-4',track:'theory',level:4,title:'Structural materials',icon:'σ/ε',color:'#BA7517',desc:'Stress and strain, the pressure vessel, creep and fatigue, fracture toughness, embrittlement and pressurised thermal shock.',lessons:[
LH('t4-4-1','Stress, strain and the pressure vessel',10,'How engineers describe the forces inside metal, and how thick a reactor vessel wall must be.',[
RM(`<ul><li>Pressure p = force ÷ area, in Pa (Level 1).</li><li>The reactor pressure vessel holds water at 155 bar = 15.5 MPa (Level 1 Theory).</li></ul>`),
T(`<h3>Stress and strain</h3><div class="eq">stress σ = F / A &nbsp;&nbsp;&nbsp; strain ε = ΔL / L &nbsp;&nbsp;&nbsp; E = σ / ε</div>${KY([['σ','stress (force per area inside the material)','Pa (MPa)'],['ε','strain (fractional stretch)','no unit'],['E','Young\'s modulus (stiffness): steel about 200 GPa','Pa']],'Here σ means stress, not cross-section. Context tells you which.')}<p>Stretch a metal and it springs back (<b>elastic</b>) until the <b>yield strength</b>; beyond that it stays bent (<b>plastic</b>). It finally breaks at the <b>ultimate tensile strength</b>.</p>`),
T(`<h3>Hoop stress in a cylinder</h3><p>Pressure inside a cylinder tries to split it along its length. For a thin wall:</p><div class="eq">σ<sub>hoop</sub> = p r / t &nbsp;&nbsp;&nbsp; σ<sub>axial</sub> = p r / (2t)</div>${KY([['p','internal pressure','Pa'],['r','inner radius','m'],['t','wall thickness','m']],'Hoop stress is twice the axial stress: that\'s why sausages split lengthways.')}`),
W('stepCalc',{steps:['EPR vessel: p = 15.5 MPa, r ≈ 2.44 m, t ≈ 0.25 m','σ<sub>hoop</sub> = 15.5 × 2.44 ÷ 0.25','= <b>151 MPa</b>','Vessel steel (SA-508) yield strength: at least about 345 MPa','Stress is under half of yield. Codes (like ASME III) also add margins for flaws, fatigue and temperature.']},`Check the stress in an EPR pressure vessel wall.`),
N(`A steam generator shell: p = 7 MPa, r = 2 m, t = 0.1 m. Hoop stress in MPa?`,140,0.01,'MPa',`7 × 2 ÷ 0.1 = 140 MPa.`),
QE(`155 bar in MPa is…`,[`15.5 MPa`,`155 MPa`,`1.55 MPa`,`1550 MPa`],0,`1 MPa = 10 bar.`),
T(`<h3>Key points</h3><ul><li><b>σ = F/A, ε = ΔL/L, E = σ/ε</b>. Elastic up to yield, then plastic.</li><li><b>Hoop stress = pr/t</b>, twice the axial stress.</li><li>EPR vessel: about 150 MPa at full pressure, under half of yield.</li></ul>`)]),
LH('t4-4-2','Creep and fatigue',10,'Two slow ways metals fail: stretching under steady load at high temperature, and cracking from repeated loading.',[
RM(`<ul><li>Stress σ = F/A; yield strength.</li><li>Cladding creeps down onto the pellets (Level 2 Theory).</li></ul>`),
T(`<h3>Creep</h3><p>At high temperature (above about 0.4 of the melting temperature in kelvin), metals slowly stretch under a constant stress, even below yield. A creep curve has three stages:</p><ol class="steps"><li><b>Primary</b>: fast at first, slowing down.</li><li><b>Secondary</b>: steady, slow stretching (most of the life).</li><li><b>Tertiary</b>: speeds up as cracks form, ending in rupture.</li></ol><p>In a PWR, zirconium cladding creeps inwards under coolant pressure until it touches the pellets. Radiation also speeds up creep (<b>irradiation creep</b>).</p>`),
T(`<h3>Fatigue</h3><p>Repeated loading, even well below yield, can grow tiny cracks until a part fails. Every heat-up and cool-down, every power change, every trip is a <b>cycle</b>.</p><p>Engineers count cycles using <b>Miner's rule</b>:</p><div class="eq">usage factor U = Σ (n<sub>i</sub> / N<sub>i</sub>) &nbsp; must stay below 1</div>${KY([['n<sub>i</sub>','number of cycles of type i actually experienced',''],['N<sub>i</sub>','number of those cycles that would cause failure (from tests)','']])}`),
W('stepCalc',{steps:['A nozzle sees 200 heat-up/cool-down cycles in its life; it could survive 2,000: 200/2000 = 0.10','It sees 400 reactor trips; it could survive 1,600: 400/1600 = 0.25','It sees 10,000 small load changes; it could survive 100,000: 0.10','U = 0.10 + 0.25 + 0.10 = <b>0.45</b>','Below 1: acceptable. Plants count real cycles so they know the actual usage.']},`Add up a fatigue usage factor.`),
N(`n/N for three types: 0.2, 0.3 and 0.15. Usage factor?`,0.65,0.01,'',`0.2 + 0.3 + 0.15 = 0.65.`),
Q(`Thermal fatigue is a worry where…`,[`hot and cold water mix, making the metal temperature swing`,'the metal stays at a constant high temperature','there is no flow and the water is still','the reactor is shut down, drained and kept cold for years'],0,`E.g. at feedwater nozzles and mixing tees.`),
QE(`Hoop stress = …`,[`pr/t`,`pr/2t`,`F × A`,`E × ε²`],0,`Last lesson.`),
T(`<h3>Key points</h3><ul><li><b>Creep</b>: slow stretching under steady load at high temperature; three stages.</li><li><b>Fatigue</b>: cracks grow from repeated cycles.</li><li><b>Miner's rule</b>: usage factor Σn/N must stay below 1.</li></ul>`)]),
LH('t4-4-3','Fracture, embrittlement and thermal shock',10,'Why an old pressure vessel must never be cooled too fast while pressurised.',[
RM(`<ul><li>Fast neutrons knock atoms out of place, making steel harder but more brittle (Level 2 Theory).</li><li>Hoop stress = pr/t.</li></ul>`),
T(`<h3>Fracture toughness</h3><p>A crack concentrates stress at its tip. How strongly is measured by the <b>stress intensity factor</b>:</p><div class="eq">K = Y σ √(π a)</div>${KY([['K','stress intensity factor','MPa√m'],['Y','shape factor (about 1)',''],['σ','applied stress','MPa'],['a','crack depth','m']])}<p>The crack grows suddenly if K reaches the material's <b>fracture toughness K<sub>IC</sub></b>.</p>`),
T(`<h3>The ductile–brittle transition</h3><p>Ferritic steels (like vessel steel) are tough when warm but become <b>brittle when cold</b>. The change happens around the <b>ductile–brittle transition temperature</b>. Fast neutrons push this temperature <b>upwards</b> over the vessel's life, especially if the steel contains copper or nickel.</p><p>Plants keep <b>surveillance capsules</b> of the same steel inside the vessel, closer to the core, and test them to see how far the transition has moved.</p>`),
W('fnPlot',{x:[-100,250],y:[0,220],xl:'metal temperature (°C)',yl:'toughness K<sub>IC</sub> (MPa√m)',sl:[['s','Transition shift from irradiation (°C)',0,150,10,0,function(v){return '+'+v+' °C'}]],lines:[[80,'--coral']],curves:function(p){return [[function(T){return kic(T,0)},'--muted',1.5,[6,4]],[function(T){return kic(T,p.s)},'--accent',3]]},marks:function(p,P,col){var c=P.c;c.fillStyle=col('--text');c.beginPath();c.arc(P.X(60),P.Y(kic(60,p.s)),6,0,7);c.fill()},read:function(p){var k=kic(60,p.s);return 'At 60 °C (cold water injected during a fault) toughness is <b>'+k.toFixed(0)+' MPa√m</b>; the crack loading (orange line) is 80. '+(k<80?'<b>Brittle fracture is possible.</b>':'Still tough enough.')},goal:function(p){return kic(60,p.s)<80},goalMsg:'Increase the irradiation shift until 60 °C becomes dangerous.'},`See how irradiation shifts the transition. Dashed: new steel. Solid: irradiated.`,`An old, irradiated vessel can be brittle at temperatures where new steel is perfectly tough.`),
T(`<h3>Pressurised thermal shock (PTS)</h3><p>Imagine a fault that injects cold water into a hot vessel <b>while it is still pressurised</b>:</p><ul><li>the inner surface cools quickly and contracts, creating high <b>thermal stress</b>,</li><li>the pressure adds hoop stress on top,</li><li>and the cold inner surface may be below the (shifted) transition temperature.</li></ul><p>That combination could grow a crack. To prevent it, operators follow <b>pressure–temperature limit curves</b> during heat-up and cool-down, and procedures limit repressurising a cold vessel.</p>`),
QE(`Which steels have no ductile–brittle transition?`,[`Austenitic stainless steels`,`Ferritic low-alloy vessel steels`,`All carbon and alloy steels`,`Plain carbon steels`],0,`Their crystal structure stays ductile when cold.`),
T(`<h3>Key points</h3><ul><li><b>K = Yσ√(πa)</b>; fracture if K ≥ K<sub>IC</sub>.</li><li>Irradiation <b>raises the transition temperature</b> of vessel steel; surveillance capsules track it.</li><li><b>PTS</b>: cold water + high pressure + embrittled steel. Prevented by P–T limits and procedures.</li></ul>`)])
]});
F('t4-4-1',[T(`<h3>Quick recap</h3><p>σ = F/A; hoop = pr/t.</p>`),N(`p = 15.5 MPa, r = 2 m, t = 0.2 m. Hoop stress?`,155,0.01,'MPa',`15.5 × 10.`),Q(`Below yield, deformation is…`,[`elastic (springs back)`,`plastic`,`fracture`,`creep only`],0,`Elastic.`),N(`Stress 200 MPa, E = 200 GPa. Strain?`,0.001,0.01,'',`200e6/200e9.`)]);
F('t4-4-2',[T(`<h3>Quick recap</h3><p>Creep: steady load, high T. Fatigue: cycles; U = Σn/N.</p>`),Q(`Which creep stage lasts longest?`,[`Secondary (steady)`,`Primary`,`Tertiary`,`None`],0,`Steady creep.`),N(`n/N: 0.4 and 0.4. U?`,0.8,0.01,'',`0.8: still OK.`),Q(`Fatigue can cause failure at stresses…`,[`below the yield strength`,`only above ultimate strength`,`only at zero stress`,`never`],0,`Cracks grow cycle by cycle.`)]);
F('t4-4-3',[T(`<h3>Quick recap</h3><p>K = Yσ√(πa); irradiation raises the transition temperature.</p>`),N(`σ = 100 MPa, a = 0.01 m, Y = 1. K? (√(π × 0.01) = 0.177)`,17.7,0.02,'MPa√m',`100 × 0.177.`),Q(`Surveillance capsules are used to…`,[`measure embrittlement of vessel steel`,`store fuel`,`hold boron`,`measure flux only`],0,`Tested periodically.`),Q(`PTS needs…`,[`cold water, high pressure and embrittled steel together`,`only high temperature`,`only low pressure`,`a turbine trip`],0,`All three.`)]);
TT('t4-4',[x('t4-4-1',Q(`Hoop stress compared with axial stress is…`,[`twice as big`,`half`,`equal`,`zero`],0,`pr/t vs pr/2t.`)),x('t4-4-1',N(`p = 10 MPa, r = 1 m, t = 0.05 m. Hoop?`,200,0.01,'MPa',`10 × 20.`)),x('t4-4-2',Q(`Miner's rule requires…`,[`Σn/N < 1`,`Σn/N > 1`,`n = N`,`σ < E`],0,`Usage factor.`)),x('t4-4-2',Q(`Creep matters above about…`,[`0.4 × melting temperature (in K)`,`room temperature for all metals`,`absolute zero`,`boiling point of water`],0,`Thermally activated.`)),x('t4-4-3',Q(`Neutron irradiation makes vessel steel's transition temperature…`,[`rise`,`fall`,`disappear`,`stay fixed`],0,`More brittle.`)),x('t4-4-3',Q(`Fracture happens when K reaches…`,[`K<sub>IC</sub>`,`zero`,`yield`,`E`],0,`Fracture toughness.`))]);

U({id:'t4-5',track:'theory',level:4,title:'Radiation protection science',icon:'Sv',color:'#D4537E',desc:'How gamma rays interact with matter, attenuation and buildup, dose quantities and weighting factors, and designing a shield.',lessons:[
LH('t4-5-1','How gamma rays interact',10,'Three ways a photon gives up its energy, and which one wins at each energy.',[
RM(`<ul><li>Gamma rays are high-energy photons with no charge; dense materials like lead stop them best (Level 1 Theory).</li><li>Energy in MeV; 1 MeV is a typical reactor gamma.</li></ul>`),
T(`<h3>Three main processes</h3><ul><li><b>Photoelectric effect</b>: the photon is absorbed completely and knocks out an inner electron. Dominant at <b>low energy</b> and in <b>high-Z</b> materials (probability ∝ about Z⁴/E³).</li><li><b>Compton scattering</b>: the photon bounces off an electron, losing some energy and changing direction. Dominant from about <b>0.1 to 10 MeV</b> in most materials. Depends on electron density.</li><li><b>Pair production</b>: near a nucleus, the photon turns into an electron and a positron. Needs at least <b>1.022 MeV</b> (two electron masses, E = mc²). Important at high energy in heavy materials (∝ Z²).</li></ul>`),
W('matchPairs',{pairs:[['Photoelectric effect','Photon completely absorbed, electron ejected; low energy, high Z'],['Compton scattering','Photon scatters off an electron and loses some energy'],['Pair production','Photon becomes an electron and a positron'],['1.022 MeV','Minimum energy for pair production']]},`Match each process to its description.`),
W('stepCalc',{steps:['Pair production makes an electron and a positron, each with rest mass energy 0.511 MeV.','Threshold: 2 × 0.511 = <b>1.022 MeV</b>','A 2 MeV photon makes a pair with 2 − 1.022 = <b>0.978 MeV</b> of kinetic energy to share.','The positron soon meets an electron and annihilates…','…giving two 0.511 MeV photons going in opposite directions. Those are what PET scanners detect.']},`Follow a pair production event.`),
Q(`Which process dominates for 1 MeV gammas in concrete or water?`,[`Compton scattering`,`Photoelectric effect`,`Pair production`,`Fission`],0,`0.1–10 MeV in low-Z materials.`),
QE(`E = mc²: the rest energy of an electron is…`,[`0.511 MeV`,`938.3 MeV`,`0.938 MeV`,`1.022 MeV`],0,`Level 1 Maths.`),
T(`<h3>Key points</h3><ul><li><b>Photoelectric</b>: low energy, high Z.</li><li><b>Compton</b>: medium energies (most reactor gammas).</li><li><b>Pair production</b>: above 1.022 MeV, high Z.</li></ul>`)]),
LH('t4-5-2','Attenuation, buildup and distance',10,'How thick a shield must be, why scattered photons still matter, and the inverse square law.',[
RM(`<ul><li>I = I₀e<sup>−Σx</sup> for a neutron beam (Level 4 Maths). Gammas follow the same law with μ.</li><li>Half-value layer: thickness that halves the intensity (Level 1 Theory).</li></ul>`),
T(`<h3>Narrow-beam attenuation</h3><div class="eq">I = I₀ e<sup>−μx</sup> &nbsp;&nbsp;&nbsp; HVL = ln 2 ÷ μ</div>${KY([['μ','linear attenuation coefficient','cm⁻¹'],['HVL','half-value layer','cm']])}<table><tr><th>1 MeV gammas</th><th>μ (cm⁻¹)</th><th>HVL</th></tr><tr><td>Lead</td><td>0.77</td><td>0.9 cm</td></tr><tr><td>Concrete</td><td>0.15</td><td>4.7 cm</td></tr><tr><td>Water</td><td>0.071</td><td>9.8 cm</td></tr></table>`),
T(`<h3>Buildup</h3><p>The simple law counts only photons that never interacted. But Compton-scattered photons can still reach you. So in a thick shield, the real dose is higher by a <b>buildup factor B</b>:</p><div class="eq">I = B I₀ e<sup>−μx</sup> &nbsp;&nbsp; (B ≥ 1)</div><p>B can be 5–20 or more for thick concrete or water shields. Ignoring it would make a shield look better than it is.</p>`),
W('fnPlot',{x:[0,60],y:[0.0001,1],ylog:true,xl:'concrete thickness (cm)',yl:'dose rate ÷ unshielded',sl:[['x','Concrete thickness (cm)',0,60,5,20,function(v){return v+' cm'}]],curves:function(){return [[function(x){return Math.exp(-0.15*x)},'--muted',2,[6,4]],[function(x){return (1+0.15*x*1.2)*Math.exp(-0.15*x)},'--accent',3]]},marks:function(p,P,col){var c=P.c,y=(1+0.15*p.x*1.2)*Math.exp(-0.15*p.x);c.fillStyle=col('--coral');c.beginPath();c.arc(P.X(p.x),P.Y(y),6,0,7);c.fill()},read:function(p){var n=Math.exp(-0.15*p.x),B=1+0.15*p.x*1.2;return p.x+' cm: uncollided only (dashed) '+(n*100).toPrecision(2)+'%; with buildup B ≈ '+B.toFixed(1)+' (solid) <b>'+(n*B*100).toPrecision(2)+'%</b>.'}},`Thicken the concrete. Compare uncollided photons (dashed) with buildup included (solid).`),
T(`<h3>Distance: the inverse square law</h3><p>From a small (point) source, radiation spreads over a sphere of area 4πr²:</p><div class="eq">dose rate ∝ 1 / r²</div><p>Double the distance → a <b>quarter</b> of the dose rate. That's why tongs and remote tools work so well.</p>`),
N(`Dose rate is 400 μSv/h at 1 m from a small source. What is it at 4 m?`,25,0.01,'μSv/h',`400 ÷ 4² = 400 ÷ 16 = 25 μSv/h.`),
QE(`HVL = 0.9 cm. How many HVLs reduce the dose to 1/8?`,[`3`,`8`,`2`,`4`],0,`(½)³ = 1/8.`),
T(`<h3>Key points</h3><ul><li><b>I = BI₀e<sup>−μx</sup></b>; HVL = 0.693/μ.</li><li>Buildup from scattered photons makes real doses higher than the simple law.</li><li><b>Inverse square</b>: dose ∝ 1/r².</li></ul>`)]),
LH('t4-5-3','Dose quantities and limits',10,'Gray, sievert, weighting factors and the UK legal limits a Hinkley Point worker lives by.',[
RM(`<ul><li>Alpha, beta, gamma and neutrons damage tissue differently (Level 1 Theory).</li><li>ALARP: as low as reasonably practicable.</li></ul>`),
T(`<h3>From energy to risk, in three steps</h3><ol class="steps"><li><b>Absorbed dose D</b> = energy absorbed per kg of tissue. Unit: <b>gray (Gy)</b> = 1 J/kg.</li><li><b>Equivalent dose H = w<sub>R</sub> × D</b>: adjusts for how damaging the radiation type is. Unit: <b>sievert (Sv)</b>.</li><li><b>Effective dose E = Σ w<sub>T</sub> × H<sub>T</sub></b>: adds up the doses to each organ, weighted by how sensitive it is. Unit: Sv. This is the number limits are set on.</li></ol>`),
T(`<h3>Weighting factors (ICRP 103)</h3><table><tr><th>Radiation</th><th>w<sub>R</sub></th></tr><tr><td>Photons (gamma, X-ray)</td><td>1</td></tr><tr><td>Electrons (beta)</td><td>1</td></tr><tr><td>Protons</td><td>2</td></tr><tr><td>Neutrons</td><td>2.5–20 (depends on energy)</td></tr><tr><td>Alpha particles</td><td>20</td></tr></table><table><tr><th>Organ</th><th>w<sub>T</sub></th></tr><tr><td>Red bone marrow, lung, stomach, colon, breast</td><td>0.12 each</td></tr><tr><td>Gonads</td><td>0.08</td></tr><tr><td>Thyroid, bladder, liver, oesophagus</td><td>0.04 each</td></tr><tr><td>Skin, bone surface, brain, salivary glands</td><td>0.01 each</td></tr></table><p>The organ weights add up to 1.</p>`),
W('stepCalc',{steps:['A worker\'s lungs absorb 2 mGy from alpha particles (inhaled dust).','Equivalent dose to lungs: H = 20 × 2 = 40 mSv','Effective dose: E = w<sub>T</sub> × H = 0.12 × 40','= <b>4.8 mSv</b>','That\'s about a quarter of the annual worker limit, from a dose that was only 2 mGy. Why inhalation of alpha emitters is controlled so carefully.']},`Work out an effective dose.`),
N(`Whole body: 1 mGy gamma plus 0.2 mGy of neutrons with w<sub>R</sub> = 10. Equivalent dose in mSv?`,3,0.01,'mSv',`1 × 1 + 0.2 × 10 = 3 mSv.`),
T(`<h3>UK limits (Ionising Radiations Regulations 2017)</h3><table><tr><th>Who</th><th>Effective dose limit per year</th></tr><tr><td>Employees (18+)</td><td>20 mSv</td></tr><tr><td>Members of the public</td><td>1 mSv</td></tr></table><p>For comparison, the UK average from natural background is about <b>2.7 mSv a year</b>. Limits are a ceiling, not a target: <b>ALARP</b> means doses must be kept as low as reasonably practicable below them. Plants also set lower internal dose constraints.</p>`),
Q(`Which quantity are legal dose limits set on?`,[`Effective dose (Sv)`,`Absorbed dose (Gy)`,`Activity (Bq)`,`Exposure rate`],0,`It reflects whole-body risk.`),
QE(`Dose at 2 m is 100 μSv/h. At 1 m?`,[`400 μSv/h`,`200 μSv/h`,`50 μSv/h`,`25 μSv/h`],0,`Inverse square: (2/1)² = 4.`),
T(`<h3>Key points</h3><ul><li><b>Gy</b> (energy per kg) → × w<sub>R</sub> → <b>Sv</b> equivalent → Σ w<sub>T</sub> → <b>effective dose</b>.</li><li>w<sub>R</sub>: photons/beta 1, protons 2, neutrons 2.5–20, alpha 20.</li><li>UK limits: workers <b>20 mSv/yr</b>, public 1 mSv/yr. ALARP below that.</li></ul>`)])
]});
F('t4-5-1',[T(`<h3>Quick recap</h3><p>Photoelectric (low E), Compton (medium), pair (>1.022 MeV).</p>`),Q(`Photoelectric absorption is strongest in…`,[`lead, at low energy`,`water, at high energy`,`air`,`hydrogen`],0,`∝ Z⁴/E³.`),Q(`Compton scattering depends mainly on…`,[`electron density`,`neutron number`,`temperature`,`Z⁴`],0,`Scatters off electrons.`),Q(`A 0.5 MeV photon can't do pair production because…`,[`it's below 1.022 MeV`,`it's too fast`,`it has charge`,`lead is too dense`],0,`Threshold.`)]);
F('t4-5-2',[T(`<h3>Quick recap</h3><p>I = BI₀e<sup>−μx</sup>; 1/r².</p>`),N(`μ = 0.15 cm⁻¹. HVL?`,4.62,0.02,'cm',`0.693/0.15.`),N(`100 μSv/h at 3 m. At 6 m?`,25,0.01,'μSv/h',`Quarter.`),Q(`Buildup factor B is…`,[`≥ 1, from scattered photons`,`always below 1`,`the HVL`,`zero for thick shields`],0,`Adds scattered photons.`)]);
F('t4-5-3',[T(`<h3>Quick recap</h3><p>D (Gy) → H = w<sub>R</sub>D (Sv) → E = Σw<sub>T</sub>H<sub>T</sub>.</p>`),N(`0.5 mGy of alpha to one organ. Equivalent dose (mSv)?`,10,0.01,'mSv',`× 20.`),Q(`UK annual limit for employees is…`,[`20 mSv`,`1 mSv`,`50 mSv`,`100 mSv`],0,`IRR17.`),Q(`1 Gy means…`,[`1 joule absorbed per kg`,`1 decay per second`,`1 sievert always`,`1 MeV per cm`],0,`Absorbed dose.`)]);
TT('t4-5',[x('t4-5-1',Q(`Most 1 MeV gammas in water interact by…`,[`Compton scattering`,`pair production`,`photoelectric`,`fission`],0,`Mid energy.`)),x('t4-5-1',Q(`Pair production threshold is…`,[`1.022 MeV`,`0.511 MeV`,`10 MeV`,`200 MeV`],0,`Two electron masses.`)),x('t4-5-2',N(`μ = 0.77 cm⁻¹ (lead). HVL?`,0.9,0.02,'cm',`0.693/0.77.`)),x('t4-5-2',Q(`Tripling the distance from a point source makes the dose rate…`,[`1/9`,`1/3`,`3×`,`9×`],0,`Inverse square.`)),x('t4-5-3',Q(`w<sub>R</sub> for alpha particles is…`,[`20`,`1`,`2`,`10`],0,`Very damaging.`)),x('t4-5-3',Q(`UK annual public dose limit is…`,[`1 mSv`,`20 mSv`,`2.7 mSv`,`0.1 mSv`],0,`IRR17.`))]);


